(function(){
  'use strict';
  var renderQueued=false;
  function store(){try{return window.__POOL_SHED_GET_DATA__?window.__POOL_SHED_GET_DATA__():window.data}catch(_){return window.data||{}}}
  function products(){var d=store();return Array.isArray(d.products)?d.products:[]}
  function product(id){return products().find(function(p){return String(p.id)===String(id)})||null}
  function order(id){var d=store();return (d.salesOrders||[]).find(function(o){return String(o.id)===String(id)})||null}
  function loc(id){var d=store();return (d.locations||[]).find(function(l){return String(l.id)===String(id)})||null}
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]})}
  function money(v){return typeof window.money==='function'?window.money(Number(v||0)):'£'+Number(v||0).toFixed(2)}
  function save(){if(typeof window.saveAppData==='function')window.saveAppData()}
  function toast(s){if(typeof window.toast==='function')window.toast(s)}
  function refresh(){save();if(typeof window.render==='function')window.render()}
  function isBundleHead(line){return !!(line&&line.bundleRole==='head')}
  function isBundleComponent(line){return !!(line&&line.bundleRole==='component'&&line.bundleInstanceId)}
  function groups(o){var map={};(o&&o.lines||[]).forEach(function(line){if(!line.bundleInstanceId)return;var key=line.bundleInstanceId;if(!map[key])map[key]={id:key,head:null,components:[]};if(isBundleHead(line))map[key].head=line;else if(isBundleComponent(line))map[key].components.push(line)});return Object.keys(map).map(function(k){return map[k]}).filter(function(g){return g.head&&g.components.length})}
  function stockRows(pid){var d=store();return (d.stock||[]).filter(function(r){return String(r.productId)===String(pid)})}
  function available(row){return Math.max(0,Number(row.qty||0)-Number(row.allocated||0))}
  function pendingPO(o,pid){var d=store();return (d.purchaseOrders||[]).reduce(function(total,po){return total+(po.lines||[]).filter(function(l){return String(l.productId)===String(pid)&&String(l.salesOrderId||po.originalSalesOrderId||'')===String(o.id)}).reduce(function(sum,l){return sum+Math.max(0,Number(l.qty||0)-Number(l.received||0))},0)},0)}
  function mainWarehouse(){var d=store(),ls=d.locations||[];return ls.find(function(l){return l.isMaster})||ls.find(function(l){return /main|warehouse/i.test(String(l.name||''))&&/warehouse/i.test(String(l.type||l.name||''))})||ls.find(function(l){return /warehouse/i.test(String(l.type||''))})||ls[0]||null}
  function stockAnalysis(o,line){var rows=stockRows(line.productId),needed=Math.max(0,Number(line.qty||0)-Number(line.allocated||0)),main=mainWarehouse();var mainFree=rows.filter(function(r){return main&&String(r.locationId)===String(main.id)}).reduce(function(s,r){return s+available(r)},0);var elsewhere=rows.filter(function(r){return !main||String(r.locationId)!==String(main.id)}).map(function(r){return{row:r,location:loc(r.locationId),free:available(r)}}).filter(function(x){return x.free>0}).sort(function(a,b){return b.free-a.free});var transfer=Math.min(needed,elsewhere.reduce(function(s,x){return s+x.free},0));var afterTransfer=Math.max(0,needed-mainFree-transfer);var po=pendingPO(o,line.productId);return{needed:needed,mainFree:mainFree,elsewhere:elsewhere,transfer:transfer,onPO:po,toBuy:Math.max(0,afterTransfer-po)}}
  function bestRows(pid,preferMain){var rows=stockRows(pid).filter(function(r){return available(r)>0});var main=mainWarehouse();return rows.sort(function(a,b){var am=main&&String(a.locationId)===String(main.id),bm=main&&String(b.locationId)===String(main.id);if(preferMain&&am!==bm)return am?-1:1;return available(b)-available(a)})}
  function allocateLine(o,line){if(!line||isBundleHead(line))return 0;var need=Math.max(0,Number(line.qty||0)-Number(line.allocated||0)),done=0;bestRows(line.productId,true).some(function(r){var take=Math.min(need-done,available(r));if(take<=0)return false;r.allocated=Number(r.allocated||0)+take;line.allocated=Number(line.allocated||0)+take;done+=take;var d=store();if(Array.isArray(d.movements))d.movements.unshift({id:'M-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),date:new Date().toISOString(),type:'Allocation',productId:line.productId,qty:take,locationId:r.locationId,reference:o.id,jobId:o.id,user:'Bundle Intelligence',note:'Allocated bundle component'});return done>=need});return done}
  function allocateGroup(o,g){var n=0;g.components.forEach(function(l){n+=allocateLine(o,l)});updateOrderStatus(o);refresh();toast(n? n+' component unit(s) allocated to '+o.id+'.':'No additional free stock was available.')}
  function updateOrderStatus(o){var stockLines=(o.lines||[]).filter(function(l){return !isBundleHead(l)&&l.lineType!=='shipping'&&l.lineType!=='custom'});var full=stockLines.length&&stockLines.every(function(l){return Number(l.allocated||0)>=Number(l.qty||0)});var partial=stockLines.some(function(l){return Number(l.allocated||0)>0});o.status=full?'Ready To Pick':(partial?'Part Stock':'Needs Review');if(!full){o.tags=o.tags||[];if(o.tags.indexOf('Backorder')<0)o.tags.push('Backorder')}}
  function transferGroup(o,g){var main=mainWarehouse();if(!main){toast('No main warehouse location is configured.');return}var moved=0,d=store();g.components.forEach(function(line){var a=stockAnalysis(o,line),remaining=Math.max(0,a.needed-a.mainFree);a.elsewhere.forEach(function(src){if(remaining<=0)return;var qty=Math.min(remaining,src.free);if(qty<=0)return;src.row.qty=Number(src.row.qty||0)-qty;var target=(d.stock||[]).find(function(r){return String(r.productId)===String(line.productId)&&String(r.locationId)===String(main.id)});if(!target){target={productId:line.productId,locationId:main.id,qty:0,allocated:0};d.stock.push(target)}target.qty=Number(target.qty||0)+qty;remaining-=qty;moved+=qty;if(Array.isArray(d.movements))d.movements.unshift({id:'M-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),date:new Date().toISOString(),type:'Transfer',productId:line.productId,qty:qty,fromLocationId:src.row.locationId,toLocationId:main.id,locationId:main.id,reference:o.id,user:'Bundle Intelligence',note:'Recommended bundle component transfer from '+((src.location&&src.location.name)||src.row.locationId)})})});refresh();toast(moved?moved+' unit(s) transferred to '+main.name+'. Allocate the bundle to reserve them.':'No transferable stock is required or available.')}
  function nextPoId(){var d=store(),nums=(d.purchaseOrders||[]).map(function(p){var m=String(p.id||'').match(/(\d+)/);return m?Number(m[1]):0});return 'PO-'+(Math.max.apply(null,[1000].concat(nums))+1)}
  function supplierFor(p){return p&&String(p.supplier||p.vendor||p.supplierName||'').trim()||'Supplier review required'}
  function createPOs(o,g){var d=store(),bySupplier={};g.components.forEach(function(line){var a=stockAnalysis(o,line);if(a.toBuy<=0)return;var p=product(line.productId)||{};var s=supplierFor(p);(bySupplier[s]||(bySupplier[s]=[])).push({productId:line.productId,qty:a.toBuy,received:0,salesOrderId:o.id,supplierSku:p.supplierSku||'',unitCost:Number(p.cost||0),orderedDate:new Date().toISOString().slice(0,10),dueDate:o.due||'',supplierNotes:'Created for missing component in bundle '+(g.head.bundleParentName||g.head.description||product(g.head.productId)&&product(g.head.productId).name||g.head.productId)})});var ids=[];Object.keys(bySupplier).forEach(function(s){var id=nextPoId();d.purchaseOrders.push({id:id,supplier:s,status:'Draft - Review',due:o.due||'',jobId:'',originalSalesOrderId:o.id,source:'Bundle component shortage',reviewStatus:'Needs review',supplierEmailStatus:'Blocked until reviewed',customerId:o.customerId||'',lines:bySupplier[s]});ids.push(id)});if(!ids.length){toast('No new purchase quantities are required. Existing stock, transfers or linked POs cover the shortage.');return}o.status='Ordered';o.tags=o.tags||[];if(o.tags.indexOf('Backorder')<0)o.tags.push('Backorder');refresh();toast(ids.length+' supplier PO draft(s) created for missing bundle components.')}
  function summary(o,g){var rows=g.components.map(function(line){var p=product(line.productId)||{},a=stockAnalysis(o,line);var ready=Math.min(Number(line.qty||0),Number(line.allocated||0)+a.mainFree);var state=a.toBuy>0?'buy':(a.transfer>0?'transfer':(ready>=Number(line.qty||0)?'ready':'incoming'));return{line:line,p:p,a:a,state:state}});var ready=rows.filter(function(r){return r.state==='ready'}).length,transfer=rows.filter(function(r){return r.state==='transfer'}).length,buy=rows.filter(function(r){return r.state==='buy'}).length,incoming=rows.filter(function(r){return r.state==='incoming'}).length;return{rows:rows,ready:ready,transfer:transfer,buy:buy,incoming:incoming,total:rows.length}}
  function panel(o){var gs=groups(o);if(!gs.length)return'';return '<section class="bsi-panel"><div class="bsi-heading"><div><span>CONNECTED BUNDLE FULFILMENT</span><h3>Bundle intelligence</h3><p>The customer-facing bundle stays as one priced line. Stock, transfers, purchasing and picking run against the linked catalogue components.</p></div><span class="bsi-live">Live catalogue links</span></div>'+gs.map(function(g,index){var s=summary(o,g),hp=product(g.head.productId)||{},overall=s.buy?'bad':(s.transfer||s.incoming?'warn':'good');return '<article class="bsi-group '+overall+'"><header><button type="button" class="bsi-toggle" data-bsi-toggle="'+esc(g.id)+'" aria-expanded="true"><span class="bsi-chevron">⌄</span><span><strong>'+esc(hp.name||g.head.description||'Bundle')+'</strong><small>'+esc(hp.sku||g.head.productId)+' · '+s.total+' linked components</small></span></button><div class="bsi-metrics"><span class="good">'+s.ready+' ready</span><span class="warn">'+s.transfer+' transfer</span><span class="bad">'+s.buy+' purchase</span></div></header><div class="bsi-body" data-bsi-body="'+esc(g.id)+'"><div class="bsi-actions"><button type="button" data-bsi-allocate="'+esc(o.id)+'|'+esc(g.id)+'">Allocate available stock</button><button type="button" class="secondary" data-bsi-transfer="'+esc(o.id)+'|'+esc(g.id)+'" '+(s.transfer?'':'disabled')+'>Transfer internal stock</button><button type="button" class="secondary" data-bsi-po="'+esc(o.id)+'|'+esc(g.id)+'" '+(s.buy?'':'disabled')+'>Create missing-item POs</button></div><div class="bsi-table-wrap"><table class="bsi-table"><thead><tr><th>Component</th><th>Required</th><th>Allocated</th><th>Main stock</th><th>Other locations</th><th>On PO</th><th>Action</th></tr></thead><tbody>'+s.rows.map(function(r){var other=r.a.elsewhere.reduce(function(n,x){return n+x.free},0),label=r.state==='ready'?'Ready':r.state==='transfer'?'Transfer '+r.a.transfer:r.state==='buy'?'Buy '+r.a.toBuy:'Incoming PO',cl=r.state==='ready'?'good':r.state==='buy'?'bad':'warn';return '<tr><td><strong>'+esc(r.p.name||r.line.description||'Component')+'</strong><small>'+esc(r.p.sku||r.line.productId)+' · '+esc(supplierFor(r.p))+'</small></td><td>'+Number(r.line.qty||0)+'</td><td>'+Number(r.line.allocated||0)+'</td><td>'+r.a.mainFree+'</td><td>'+other+'</td><td>'+r.a.onPO+'</td><td><span class="bsi-pill '+cl+'">'+label+'</span></td></tr>'}).join('')+'</tbody></table></div></div></article>'}).join('')+'</section>'}
  function currentOrderId(){var btn=document.querySelector('#screen-salesorders [data-allocate-order]');return btn&&btn.dataset.allocateOrder||''}
  function mount(){var id=currentOrderId(),o=id&&order(id);if(!o||!groups(o).length)return;var screen=document.getElementById('screen-salesorders');if(!screen||screen.querySelector('.bsi-panel'))return;var table=screen.querySelector('.order-lines-table');var anchor=table&&table.closest('.panel')||table||screen.querySelector('.record-top');if(anchor)anchor.insertAdjacentHTML('beforebegin',panel(o))}
  function findGroup(o,id){return groups(o).find(function(g){return String(g.id)===String(id)})}
  document.addEventListener('click',function(e){var b=e.target.closest('[data-bsi-toggle]');if(b){var body=document.querySelector('[data-bsi-body="'+CSS.escape(b.dataset.bsiToggle)+'"]'),open=b.getAttribute('aria-expanded')!=='false';b.setAttribute('aria-expanded',String(!open));if(body)body.hidden=open;return}var actions=['allocate','transfer','po'];for(var i=0;i<actions.length;i++){var a=actions[i],el=e.target.closest('[data-bsi-'+a+']');if(!el)continue;var parts=el.getAttribute('data-bsi-'+a).split('|'),o=order(parts[0]),g=o&&findGroup(o,parts[1]);if(!o||!g)return;if(a==='allocate')allocateGroup(o,g);if(a==='transfer')transferGroup(o,g);if(a==='po')createPOs(o,g);return}},true);
  var observer=new MutationObserver(function(){if(renderQueued)return;renderQueued=true;requestAnimationFrame(function(){renderQueued=false;mount()})});observer.observe(document.documentElement,{childList:true,subtree:true});document.addEventListener('DOMContentLoaded',mount);setTimeout(mount,500);
  window.PoolShedBundleIntelligence={groups:groups,analyse:summary,allocate:allocateGroup,transfer:transferGroup,createPOs:createPOs};
})();
